import{_ as t,o as e,c as l,a4 as i}from"./chunks/framework.9tZL7ZIQ.js";const d=JSON.parse('{"title":"丹·伯克","description":"","frontmatter":{"title":"丹·伯克","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/丹·伯克.md","filePath":"04_people/丹·伯克.md"}'),r={name:"04_people/丹·伯克.md"};function s(o,a,h,n,_,p){return e(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="丹·伯克" tabindex="-1">丹·伯克 <a class="header-anchor" href="#丹·伯克" aria-label="Permalink to &quot;丹·伯克&quot;">​</a></h1><ul><li><strong>角色职位</strong>：首都城市/ABC 管理层</li><li><strong>与巴菲特关系</strong>：与巴菲特合作管理ABC和首都城市的管理者伙伴</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>丹·伯克在伯克希尔·哈撒韦收购首都城市通信公司（Capital Cities/ABC）的过程中发挥了关键作用。1985年，伯克希尔以重金收购首都城市通信公司，伯克担任重要管理职务，随后该公司与美国广播公司（ABC）合并成立Capital Cities/ABC。在此后长达数十年的合作中，丹·伯克与巴菲特建立了深厚的信任关系，共同管理这一大型传媒集团。</p><p>丹·伯克的管理风格务实稳健，注重业务的长期健康发展。他与汤姆·墨菲（Tom Murphy）紧密协作，墨菲负责整体战略方向，伯克则负责具体运营执行，两人的配合被巴菲特多次称赞为&quot;梦之队&quot;。在他们的共同领导下，Capital Cities/ABC成为伯克希尔旗下重要的媒体业务板块。</p><p>丹·伯克对伯克希尔的媒体业务扩张做出了重要贡献。1995年，在他的参与决策下，伯克希尔进一步收购了WTVJ等电视台，进一步扩大了在广播、电视领域的布局。这些决策体现了伯克对于媒体行业趋势的精准判断，以及与巴菲特在资本配置上的一致理念。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1985年</strong>：与巴菲特合作完成Capital Cities对ABC的收购案，成立Capital Cities/ABC</li><li><strong>1990年代初期</strong>：与汤姆·墨菲共同管理Capital Cities/ABC，确保业务稳健运营</li><li><strong>1995年</strong>：参与决策收购WTVJ等电视台资产，进一步扩大媒体版图</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=丹·伯克在2014年股东信中的原话">2014年：完整翻译|/01_letters/2014年/翻译</a></li><li><a href="/search.html?q=丹·伯克在2011年股东信中的原话">2011年：完整翻译|/01_letters/2011年/翻译</a></li><li><a href="/search.html?q=丹·伯克在2016年股东信中的原话">2016年：完整翻译|/01_letters/2016年/翻译</a></li><li><a href="/search.html?q=丹·伯克在2015年股东信中的原话">2015年：完整翻译|/01_letters/2015年/翻译</a></li><li><a href="/search.html?q=丹·伯克在2017年股东信中的原话">2017年：完整翻译|/01_letters/2017年/翻译</a></li></ul>',11)])])}const C=t(r,[["render",s]]);export{d as __pageData,C as default};
